    var deep_analysis_report_default = "/* Result layout: report first, charts beside it, raw steps collapsed last. */\n\n.deep-result-card .ant-card-body {\n  display: flex;\n  flex-direction: column;\n}\n\n.deep-result-card .ant-card-body > .deep-answer {\n  order: 1;\n}\n\n.deep-result-card .ant-card-body > .deep-artifacts {\n  order: 2;\n  margin-top: 18px;\n}\n\n.deep-result-card .ant-card-body > .deep-steps-block {\n  order: 3;\n  margin: 22px 0 4px;\n}\n\n/* Wide screens: charts sit beside the report (no sticky, so nothing overlaps). */\n@media (min-width: 1360px) {\n  .deep-result-card .ant-card-body {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) 300px;\n    column-gap: 24px;\n    align-items: start;\n  }\n\n  .deep-result-card .ant-card-body > * {\n    grid-column: 1 / -1;\n    min-width: 0;\n  }\n\n  .deep-result-card .ant-card-body > .deep-answer {\n    grid-column: 1;\n  }\n\n  .deep-result-card .ant-card-body > .deep-artifacts {\n    grid-column: 2;\n    margin-top: 0;\n    align-self: start;\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n/* Collapsed execution log */\n.deep-steps-block > summary {\n  cursor: pointer;\n  padding: 7px 12px;\n  font-size: 12px;\n  color: #62646c;\n  background: #f7f7f8;\n  border: 1px solid #e5e5e7;\n  border-radius: 9px;\n  list-style: none;\n  user-select: none;\n}\n\n.deep-steps-block > summary::-webkit-details-marker {\n  display: none;\n}\n\n.deep-steps-block > summary::before {\n  content: '\u25B8';\n  display: inline-block;\n  margin-right: 7px;\n  color: #b08a6f;\n}\n\n.deep-steps-block[open] > summary::before {\n  content: '\u25BE';\n}\n\n.deep-steps-block[open] > summary {\n  margin-bottom: 10px;\n}\n\n.deep-steps-block .deep-steps {\n  margin: 0;\n}\n\n/* Artifact cards: preview, name, explicit download */\n.deep-artifacts {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 12px;\n  min-width: 0;\n}\n\n.deep-artifacts h3 {\n  grid-column: 1 / -1;\n  margin: 0;\n  font-size: 13px;\n  font-weight: 600;\n  color: #202124;\n}\n\n.deep-artifacts h3 small {\n  margin-left: 8px;\n  font-weight: 400;\n  font-size: 11px;\n  color: #62646c;\n}\n\n.deep-artifacts .deep-artifact {\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n  margin: 0;\n  padding: 9px;\n  min-width: 0;\n  background: #fff;\n  border: 1px solid #e5e5e7;\n  border-radius: 12px;\n}\n\n.deep-artifacts .deep-artifact-preview {\n  display: block;\n  width: 100%;\n  border-radius: 8px;\n  overflow: hidden;\n  background: #fff;\n  line-height: 0;\n  cursor: zoom-in;\n}\n\n.deep-artifacts .deep-artifact-preview img {\n  width: 100%;\n  max-height: 190px;\n  object-fit: contain;\n  border-radius: 8px;\n  background: #fff;\n  transition: transform .18s ease;\n}\n\n.deep-artifacts .deep-artifact-preview:hover img {\n  transform: scale(1.015);\n}\n\n.deep-artifacts .deep-artifact-icon {\n  align-self: center;\n  margin: 12px 0;\n  font-size: 26px;\n  color: #c2a894;\n}\n\n.deep-artifacts figcaption {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: 11.5px;\n  color: #6b5346;\n}\n\n.deep-artifacts figcaption span {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.deep-artifacts figcaption small {\n  flex: none;\n  color: #62646c;\n}\n\n.deep-artifacts .deep-artifact-download {\n  align-self: flex-start;\n  padding: 3px 10px;\n  font-size: 11.5px;\n  color: var(--shell-accent);\n  background: #f7f7f8;\n  border: 1px solid #e5e5e7;\n  border-radius: 999px;\n  text-decoration: none;\n}\n\n.deep-artifacts .deep-artifact-download:hover {\n  background: #f6e8da;\n  color: #7d3f2c;\n}\n\n/* Give the result card most of the width so the report stays readable. */\n@media (min-width: 1500px) {\n  .deep-columns {\n    grid-template-columns: 360px minmax(0, 1fr);\n  }\n}\n\n/* Report typography: readable measure, calmer headings. */\n.deep-answer {\n  max-width: 820px;\n  font-size: 13.5px;\n  line-height: 1.95;\n}\n\n.deep-answer .assistant-markdown h3 {\n  font-size: 15px;\n  margin: 22px 0 10px;\n  padding-bottom: 6px;\n  border-bottom: 1px solid #e5e5e7;\n}\n\n.deep-answer .assistant-markdown :is(h4, h5, h6) {\n  margin: 16px 0 8px;\n}\n\n.deep-answer .assistant-markdown p {\n  margin: 0 0 12px;\n}\n\n.deep-answer .assistant-markdown table {\n  font-size: 12.5px;\n}\n\n.deep-answer .assistant-markdown :is(ul, ol) {\n  margin: 0 0 12px;\n}\n";

